criteria = ["Task distribution", "Replay", "Simplicity", "Fan-out"]
queue = [4, 0, 4, 1]
log = [2, 4, 1, 4]
record = {"key": "order-17", "eventId": "evt-9001", "eventType": "OrderPlaced"}
print("Partition grouping:", record["key"], "| deduplication:", record["eventId"])

averages = {}
for name, scores in [("Task queue", queue), ("Event log", log)]:
    averages[name] = sum(scores) / len(scores)
    print(name, "average:", averages[name])

weights = [1, 1, 3, 1]
table = []
for name, scores in [("Task queue", queue), ("Event log", log)]:
    total = 0
    for score, weight in zip(scores, weights):
        total += score * weight
    result = total / sum(weights)
    table.append((name, result))
    print(name, round(result, 2))
if table[0][1] > table[1][1]:
    print("Winner:", table[0][0])
elif table[1][1] > table[0][1]:
    print("Winner:", table[1][0])
else:
    print("Tie")

